IDS = BATCH['B04']+BATCH['B05']+BATCH['B06']
assert len(IDS)==60, len(IDS)

def T(cm=False, ru=False, di=False, reason=""):
    return {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":reason}
NT = T()
# entries: cid -> (prediction_text, basis, confidence, trigger)
E={}
def add(cid, pred, basis, conf, trig=NT):
    E[cid]=(pred,basis,conf,trig)

